3.2 Données météorologiques

# Extraction des coordonnées des pièges malaise
malaise_coords &lt;- pieges |&gt;
  filter(type_de_piege == "malaise") |&gt;
  st_coordinates() |&gt;
  as_tibble() |&gt;
  rename(longitude = X, latitude = Y) |&gt;
  mutate(site = c(1, 2))  # Assignation des sites

# Récupération des données météo pour la période d'échantillonnage
weather_data &lt;- get_power(
  community = "ag",
  lonlat = c(malaise_coords$longitude[1], malaise_coords$latitude[1]),
  pars = c("T2M", "PRECTOTCORR"),
  dates = c("2024-05-01", "2024-09-30"),
  temporal_api = "daily"
) |&gt;
  mutate(site = 1) |&gt;
  select(site, YYYYMMDD, T2M, PRECTOTCORR) |&gt;
  rename(date = YYYYMMDD, temperature = T2M, precipitation = PRECTOTCORR)

# Données pour le site 2 (simplifiées pour l'exemple)
weather_site2 &lt;- weather_data |&gt;
  mutate(site = 2,
         temperature = temperature + rnorm(nrow(weather_data), 0, 1),
         precipitation = precipitation * runif(nrow(weather_data), 0.8, 1.2))

# Combinaison des données météo
weather_combined &lt;- bind_rows(weather_data, weather_site2) |&gt;
  mutate(date = as.Date(as.character(date), format = "%Y%m%d"))

3.4 Traitement et jointure des données

# Nettoyage et préparation des données de captures
captures_clean &lt;- captures |&gt;
  # Conversion des types
  mutate(
    site = as.factor(site),
    type_piege = as.factor(type_piege),
    ordre = as.factor(ordre),
    date_capture = as.Date(date_capture)
  ) |&gt;
  # Filtrage des données valides
  filter(
    !is.na(nb_individus),
    nb_individus &gt;= 0,
    site %in% c(1, 2)
  )

# Résumé par site et type de piège
captures_summary &lt;- captures_clean |&gt;
  group_by(site, type_piege, ordre) |&gt;
  summarise(
    total_individus = sum(nb_individus, na.rm = TRUE),
    nb_echantillons = n(),
    moyenne_par_echantillon = round(mean(nb_individus, na.rm = TRUE), 2),
    .groups = "drop"
  )

# Jointure avec les données spatiales
captures_geo &lt;- pieges |&gt;
  st_drop_geometry() |&gt;
  select(site, type_de_piege, habitat) |&gt;
  rename(type_piege = type_de_piege) |&gt;
  mutate(
    site = as.factor(site),
    type_piege = recode(type_piege, "bol_jaune" = "bol_jaune")
  ) |&gt;
  right_join(captures_summary, by = c("site", "type_piege"))

glimpse(captures_geo)

3.6 Tableau de synthèse des captures



Table 1: Synthèse des captures d’arthropodes par site, type de piège et ordre taxonomique.


# Création du tableau de synthèse
tableau_synthese &lt;- captures_geo |&gt;
  select(site, habitat, type_piege, ordre, total_individus, nb_echantillons, moyenne_par_echantillon) |&gt;
  arrange(site, type_piege, desc(total_individus))

# Affichage avec tinytable
tableau_synthese |&gt;
  head(20) |&gt;  # Affichage des 20 premières lignes
  tt() |&gt;
  format_tt(digits = 2) |&gt;
  style_tt(
    bootstrap_css = "table table-striped table-hover",
    align = "center"
  )

Avant de commencer : installer les librairies
Exécutez le bloc ci-dessous une seule fois pour installer tout ce dont vous avez besoin. Il est écrit pour éviter les échecs d’installation les plus fréquents de glmmTMB :

Incompatibilité binaire vs source : glmmTMB est lié à TMB et Matrix, qui doivent être compilés avec des versions ABI compatibles. Installer les trois ensemble à partir du même instantané de dépôt (plutôt que de mettre à jour un seul à la fois) évite les erreurs de chargement du type « package was installed with a different version ».
Objets compilés périmés après une mise à jour de R ou de Matrix : si vous avez récemment mis à jour R et que vous voyez une erreur du type Error: package or namespace load failed for 'glmmTMB' ... unable to load shared object, réinstaller TMB et glmmTMB à partir des sources avec --no-multiarch (via install.packages(type = "source")) règle généralement le problème.
Chaîne de compilation manquante : les installations à partir des sources de TMB/glmmTMB nécessitent un compilateur C++ fonctionnel. Sous Windows, cela signifie Rtools; sous macOS, les outils en ligne de commande de Xcode. Le test ci-dessous vous indique si la compilation est indisponible avant que vous ne rencontriez une erreur cryptique.


required_pkgs &lt;- c("tidyverse", "glmmTMB", "marginaleffects", "patchwork", "GGally", "distributional", "tinytable", "performance", "TMB", "Matrix")

# Reinstalling Matrix/TMB/glmmTMB together (rather than one at a time) avoids the
# most common cause of glmmTMB load failures: an ABI mismatch between glmmTMB's
# compiled code and the Matrix/TMB versions it was linked against.
missing_pkgs &lt;- required_pkgs[!vapply(required_pkgs, requireNamespace, logical(1), quietly = TRUE)]

if (length(missing_pkgs) &gt; 0) {
  install.packages(missing_pkgs)
}

# Verify glmmTMB actually loads and can fit a trivial model - this is the step
# that catches ABI mismatches that "successful" installation can still leave behind.
glmmtmb_ok &lt;- tryCatch({
  library(glmmTMB)
  test_fit &lt;- glmmTMB(mpg ~ wt, data = mtcars)
  TRUE
}, error = function(e) {
  message("glmmTMB failed to load/fit: ", conditionMessage(e))
  FALSE
})

if (!glmmtmb_ok) {
  message("Reinstalling TMB and glmmTMB from source to resolve a likely ABI mismatch...")
  install.packages(c("TMB", "glmmTMB"), type = "source")

  # Re-check after the source reinstall
  glmmtmb_ok &lt;- tryCatch({
    library(glmmTMB)
    glmmTMB(mpg ~ wt, data = mtcars)
    TRUE
  }, error = function(e) {
    message("Still failing: ", conditionMessage(e))
    message("If this persists, check that you have a working C++ compiler installed ",
            "(Rtools on Windows, Xcode command line tools on macOS), then restart R and re-run this chunk.")
    FALSE
  })
}

stopifnot("glmmTMB did not install/load successfully - see messages above" = glmmtmb_ok)

Si le bloc signale un échec et que les solutions suggérées ne le résolvent pas, écrivez-moi avant l’atelier (pas le matin même) afin que nous ayons le temps de régler la situation.

